Consultation & Prescriptions Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("consultation_prescriptions_service", "Consultation & Prescriptions Service") {
    Component("Consultation Controller", "Consultation Controller", "Go/gRPC", "Exposes gRPC endpoints for consultation management, video session coordination, and clinician interaction.")
    Component("Prescription Manager", "Prescription Manager", "Go", "Handles business logic for cross-border e-prescriptions and coordinates with external pharmacy gateways.")
    Component("Prescription Data Access", "Prescription Data Access", "Go / SQL Driver", "Persists and retrieves consultation history and prescription records with regional data residency enforcement.")
}

Rel("Consultation Controller", "Prescription Manager", "Delegates e-prescription workflow requests")
Rel("Prescription Manager", "Prescription Data Access", "Reads and writes prescription state")
@enduml

AI Traceability & Logging Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ai_traceability_logging_service, "AI Traceability & Logging Service") {
    Component(AI_Logging_API_Controller, "AI Logging API Controller", "Python/FastAPI", "Exposes REST endpoints for ingestion and auditing of AI inference logs and traceability records.")
    Component(Audit_Traceability_Processor, "Audit & Traceability Processor", "Python/FastAPI / Pandas", "Processes, normalizes, and structures audit logs for compliance with EU MDR and regional requirements.")
    Component(Export_Formatter, "Export Formatter", "Python/FastAPI", "Generates exportable audit reports and compliance logs for review by compliance officers.")
}

Rel(AI_Logging_API_Controller, Audit_Traceability_Processor, "Ingests and forwards logs for normalization and validation", "")
Rel(Audit_Traceability_Processor, Export_Formatter, "Feeds processed audit trails for reporting and export", "")

@enduml

Consent & Policy Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(consent_and_policy_engine, "Consent & Policy Engine") {
    Component(PolicyDecisionPoint, "Policy Decision Point (PDP)", "Open Policy Agent", "Evaluates sub-millisecond ABAC and purpose-based consent rules.")
    Component(ConsentRepositoryProxy, "Consent Repository Proxy", "Go", "Proxies requests to the consent datastore enforcing regional data residency.")
    Component(AuditTraceabilityPublisher, "Audit & Traceability Publisher", "Go", "Asynchronously publishes policy decisions and audit logs to WORM storage.")
}

Rel(PolicyDecisionPoint, ConsentRepositoryProxy, "Internal Go interface", "")
Rel(PolicyDecisionPoint, AuditTraceabilityPublisher, "Asynchronous channel", "")

@enduml

Patient Portal App.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(patient_portal_app, "Patient Portal App") {
    Component(patient_portal_ui, "Patient Portal UI", "Flutter (Web & Mobile)", "Cross-platform user interface for patients, supporting web and mobile views with offline caching.")
    Component(symptom_checker_ui_module, "Symptom Checker UI Module", "Flutter", "Interactive UI module for patients to input symptoms and interact with the AI symptom checker.")
    Component(consultation_and_record_manager, "Consultation & Record Manager", "Flutter", "Manages video consultation links, e-prescriptions, and local cached patient records.")
}

Rel(patient_portal_ui, symptom_checker_ui_module, "Renders AI symptom triage workflow", "")
Rel(patient_portal_ui, consultation_and_record_manager, "Displays video sessions and e-prescriptions", "")
@enduml

Clinician Workspace App.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(clinician_workspace_app, "Clinician Workspace App") {
    Component(Clinician_UI_Router, "Clinician UI Router", "React Router / TypeScript", "Manages single-page application navigation and view rendering for clinicians.")
    Component(Consultation_View_Controller, "Consultation View Controller", "React / TypeScript", "Handles video consultation interfaces, WebRTC streaming controls, and session management.")
